func OnboardingProgressAcceptance(catalogs []*Catalog) ([]*Catalog, error) {
	selected, err := requiredAcceptance(catalogs, http.MethodPost, []string{"/api/v1/onboarding/progress"}, RequiredOnboardingProgressScenarios)
	if err != nil {
		return nil, err
	}
	var specs map[string]any
	if err := json.Unmarshal([]byte(onboardingProgressSpecs), &specs); err != nil {
		return nil, err
	}
	for _, c := range selected {
		for _, r := range c.Rows {
			for _, s := range r.Scenarios {
				raw, err := json.Marshal(s)
				if err != nil {
					return nil, err
				}
				var got any
				if err := json.Unmarshal(raw, &got); err != nil {
					return nil, err
				}
				if !reflect.DeepEqual(got, specs[s.ID]) {
					return nil, fmt.Errorf("%s: changed original or guarded progress exchange", s.ID)
				}
			}
		}
	}
	return selected, nil
}
